import{_ as l,c as i,o,ah as r}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART2/21/0_context_summary.md","filePath":"scripts/output/PART2/21/0_context_summary.md"}'),a={name:"scripts/output/PART2/21/0_context_summary.md"};function e(n,t,s,_,c,u){return o(),i("div",null,[...t[0]||(t[0]=[r('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇围绕“没有谎言的娱乐”与“无谎时代的粉丝关系”展开，记录SKY-HI在日经跨行业论坛上的演讲。他认为，粉丝并非单纯制造数字的消费群体，艺人与粉丝应在彼此尊重、各司其职的基础上共同推动文化发展。艺人需要以真实的表达建立共鸣，粉丝也应避免将支持简化为即时互动或个人回馈。文章进一步介绍B-Town的定位、BMSG的企业理念、人才培养与海外发展构想，并展望BMSG FES如何通过“认真做文化祭”的方式，强化艺人之间的联系与组织文化。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>人物身份统一</strong>：SKY-HI为日高光启的艺名；首次出现时建议保留“SKY-HI（日高光启）”，后文按原文使用。</li><li><strong>公司与团体名称</strong>：BMSG、BE:FIRST、MAZZEL、Novel Core、B-Town、BMSG FES、BMSG EAST/WEST、THE FIRST均应保留官方英文及大小写。</li><li><strong>行业术语</strong>： <ul><li>“ファンダムの力”建议译为“粉丝圈层的力量”或“粉丝群体的力量”；</li><li>“推し活”可译为“追星活动”，必要时保留“推し活”并加注；</li><li>“啓蒙”不宜译成带有居高临下意味的“教化”，可根据语境译为“引导”“启发”；</li><li>“オンラインサロン”建议译为“线上会员社群/线上沙龙”，首次出现可保留日文概念。</li></ul></li><li><strong>核心比喻</strong>：以“エリンギ（杏鲍菇）冒充牛肉、牛肉、豆制肉”比喻艺人无法长期伪装自我，需保留荒诞感和口语节奏。</li><li><strong>价值判断风险</strong>：涉及“娱乐圈混乱”“粉丝也负有责任”等内容，需保持原文的自省和批判，不应强化为对整个行业或粉丝群体的指责。</li><li><strong>语气层次</strong>：主持人部分应专业、客观；SKY-HI回答兼具管理者的逻辑性、艺术家的激情，以及适度自嘲和口语感。</li><li><strong>概念辨析</strong>：“粉丝至上的偶像”并非否定粉丝，而是反对艺人创作意志被即时反馈完全取代，译文应避免造成对立。</li><li><strong>疑似原文错乱</strong>：后半段关于B-Town直播和幕后内容的段落存在明显脱漏、重复及语序异常，如“提供および共有できるのすね”“时代ががB-Town”等，翻译前应依据上下文校订，必要时标注待核。</li><li><strong>“世界”部分</strong>：关于日本市场“加拉帕戈斯化”的论述带有行业观察性质，需保留其复杂性，不宜简单译成“日本市场封闭落后”。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>将“嘘がない”统一处理为“没有谎言”“真实、不虚假”或“真诚”，建议根据句法交替使用，避免机械重复。</li><li>准确区分“粉丝能主动推动数字增长”与“艺人必须提供值得支持的真实内容”两层逻辑。</li><li>保留演讲的现场感：主持人提问使用自然书面口语，SKY-HI回答保持第一人称、直接、富有节奏的表达。</li><li>“心からのコミュニケーション”“言葉や心の服を脱ぐ”等表达应译得有感染力，但避免过度文学化。</li><li>注意“ファンとの共創”不是普通的营销合作，宜译为“与粉丝共创”或“共同创造”，突出共同参与文化和事业建设。</li><li>对“火、风、文化祭”等反复出现的意象保持译法一致，形成全文内部呼应。</li><li>保留数字、时间、金额和课程名称：月费5000日元、Architect会员超过1万人、自筹资金超过1亿日元、众筹4.5亿日元等。</li><li>对明显错字或录音整理错误，原则上先按上下文修复，但不能擅自补充事实；无法确认时应提交编辑核对。</li></ul>',6)])])}const m=l(a,[["render",e]]);export{d as __pageData,m as default};
